"""20 vulnerability patterns, SWC-aligned.

Fields: swc, title, severity, category, description, mitigation.
Source of record: Smart Contract Weakness Classification (swcregistry.io).
"""

SEVERITY_RANK = {"critical": 4, "high": 3, "medium": 2, "low": 1}

VULNERABILITIES = [
    dict(swc="SWC-100", title="Signature Replay", severity="critical", category="cryptographic",
         description="A signature created for one chain or context can be replayed on another (or in a different function) because the domain separator is missing or weak.",
         mitigation="Use EIP-712 typed structured data with unique domain separators."),
    dict(swc="SWC-101", title="Arbitrary Transfer via Arbitrary Call", severity="high", category="access_control",
         description="A privileged call path allows moving or burning arbitrary assets via an attacker-controlled calldata or recipient.",
         mitigation="Validate destinations, cap amounts, and gate the call path behind role-based access control."),
    dict(swc="SWC-102", title="State Change After External Call", severity="medium", category="check_effects_interactions",
         description="Contract state is modified after an external call, leaving a window for re-entrancy or callback abuse.",
         mitigation="Follow the Checks-Effects-Interactions ordering: validate, update state, then call out."),
    dict(swc="SWC-103", title="Transaction Order Dependence (Front-Running)", severity="medium", category="front_running",
         description="Contract logic depends on transaction ordering, so a mempool observer can frontrun or sandwich the trade.",
         mitigation="Avoid time/order-sensitive state transitions; use commit-reveal or sealed-bid designs."),
    dict(swc="SWC-104", title="Check-Effect-Interaction Violation", severity="high", category="reentrancy",
         description="The contract interacts with an external contract before its internal state fully reflects the effect of the call.",
         mitigation="Apply reentrancy guards and reorder effects before interactions."),
    dict(swc="SWC-105", title="Flash Loan Attack", severity="high", category="economic",
         description="A large uncollateralized loan taken within a single transaction is used to distort prices or trigger liquidations, then repaid in the same transaction.",
         mitigation="Use TWAP or oracle-based pricing; cap flash-loan-triggered state changes; validate invariant conditions after callbacks."),
    dict(swc="SWC-106", title="Price Manipulation", severity="high", category="economic",
         description="On-chain spot prices can be temporarily distorted (e.g., via large swaps) to misprice collateral or liquidation thresholds.",
         mitigation="Prefer time-weighted oracles (Chainlink, TWAMM) over spot prices for settlement-critical decisions."),
    dict(swc="SWC-107", title="Reentrancy", severity="high", category="reentrancy",
         description="An external callback (transfer, flash loan, receive) re-enters the contract before state is fully updated, allowing repeated withdrawals.",
         mitigation="Use nonReentrant guards and the Checks-Effects-Interactions pattern; validate the caller of callback functions."),
    dict(swc="SWC-108", title="Access Control", severity="critical", category="access_control",
         description="A sensitive function lacks or misapplies an authorization check, letting an unprivileged caller execute privileged actions.",
         mitigation="Apply modifiers to every privileged function; initialize access control in a guarded initializer."),
    dict(swc="SWC-109", title="Delegate Call to Untrusted Contract", severity="critical", category="access_control",
         description="delegatecall into an unverified or upgradeable target lets the callee execute in the caller's storage context and overwrite state.",
         mitigation="Only delegatecall to audited, trusted code; pin implementation addresses."),
    dict(swc="SWC-111", title="Public Minter", severity="high", category="access_control",
         description="Token minting is callable without access control, enabling unbounded issuance and inflation.",
         mitigation="Restrict minting to a role or pause it; cap supply where possible."),
    dict(swc="SWC-112", title="Unprotected Initialize Function", severity="high", category="access_control",
         description="An upgradeable contract's initialize function can be called by anyone before the owner sets it up.",
         mitigation="Use initializers with onlyInitializing + nonReentrant guards and initialize at deploy time."),
    dict(swc="SWC-113", title="Missing Zero-Address Check", severity="medium", category="input_validation",
         description="Funds or ownership can be sent to address(0), making them unrecoverable.",
         mitigation="Assert recipient != address(0) on transfers and ownership transfers."),
    dict(swc="SWC-115", title="Integer Overflow / Underflow", severity="medium", category="arithmetic",
         description="Arithmetic wraps at the boundary (pre-0.8 Solidity) leading to incorrect balances, shares, or prices.",
         mitigation="Use Solidity 0.8+ checked math or an audited SafeMath library; validate inputs."),
    dict(swc="SWC-117", title="Unprotected Withdrawal Function", severity="high", category="access_control",
         description="A withdrawal or rescue function can be called without proper authorization, draining contract balances.",
         mitigation="Gate withdrawals to the owner or the affected account only."),
    dict(swc="SWC-120", title="Privileged Transaction", severity="critical", category="access_control",
         description="A privileged operation (mint, cross-chain attestation, admin action) is executed with insufficient signer verification or a compromised quorum.",
         mitigation="Verify the full signature set on-chain; rotate key material; require multisig quorums for privileged paths."),
    dict(swc="SWC-122", title="Timestamp Dependence", severity="medium", category="input_validation",
         description="Logic depends on block.timestamp, which miners/validators can skew within a bounded window.",
         mitigation="Use coarse time windows with tolerance; avoid exact-timestamp comparisons for settlement."),
    dict(swc="SWC-125", title="Unchecked Return Value", severity="medium", category="input_validation",
         description="A low-level call's success return is not checked, so a failed external call is treated as success.",
         mitigation="Check the (bool success, ...) tuple from low-level calls and handle the failure path."),
    dict(swc="SWC-127", title="Uninitialized Storage", severity="high", category="state",
         description="A storage pointer variable is used before it points to a deployed contract, causing silent writes to the wrong slot.",
         mitigation="Use an explicit initializer pattern that sets and verifies the storage pointer."),
    dict(swc="SWC-128", title="Oracle Manipulation", severity="high", category="economic",
         description="An oracle price source can be manipulated (stale quote, flash loan on the feed source, bad rounding) causing incorrect settlement or liquidation.",
         mitigation="Use trusted, frequently updated off-chain oracles; add staleness and deviation checks before settling."),
]
